DO $$ DECLARE def text;old text;BEGIN
SELECT pg_get_functiondef('public.payroll_prepare(uuid,integer,integer)'::regprocedure) INTO def;
old:='INSERT INTO public.hr_payroll(tenant_id,employee_id,year,month,forecast_base_salary,forecast_allowances,earned_salary_override,annual_leave_pay,unpaid_leave_deduction,gross_salary,mpf_employee,mpf_employer,net_salary,mpf_payment_amount,total_deductions,payment_status,preparation) VALUES(t,(r->>''employee_id'')::uuid,y,m,(r->>''forecast_base_salary'')::numeric,(r->>''forecast_allowances'')::numeric,(r->>''earned_salary_override'')::numeric,(r->>''annual_leave_pay'')::numeric,(r->>''unpaid_leave_deduction'')::numeric,(r->>''gross_salary'')::numeric,(r->>''mpf_employee'')::numeric,(r->>''mpf_employer'')::numeric,(r->>''net_salary'')::numeric,(r->>''mpf_payment_amount'')::numeric,(r->>''mpf_employee'')::numeric,''draft'',r->''preparation'')';
IF strpos(def,old)=0 THEN RAISE EXCEPTION 'Pay starting point insert not found';END IF;
def:=replace(def,old,'INSERT INTO public.hr_payroll SELECT (jsonb_populate_record(NULL::public.hr_payroll,jsonb_build_object(''forecast_deductions'',0,''forecast_overtime'',0,''forecast_bonus'',0,''forecast_total'',0,''annual_leave_pay'',0,''statutory_holiday_pay'',0,''other_payments'',0,''sick_leave_deduction'',0,''unpaid_leave_deduction'',0,''other_deductions'',0,''payment_method'',''bank_transfer'')||jsonb_strip_nulls(r)||jsonb_build_object(''id'',gen_random_uuid(),''tenant_id'',t,''employee_id'',(r->>''employee_id'')::uuid,''year'',y,''month'',m,''salary_paid_amount'',0,''mpf_paid_amount'',0,''payment_status'',''draft'',''created_at'',now(),''updated_at'',now()))).*');EXECUTE def;
SELECT pg_get_functiondef('public.payroll_override(uuid,uuid,text,numeric,numeric,text,boolean,integer)'::regprocedure) INTO def;
def:=replace(def,'IF f NOT IN (''adjustments_override'',''earned_salary_override'',''actual_overtime'',''actual_bonus'',''forecast_allowances'')','IF f NOT IN (''adjustments_override'',''earned_salary_override'',''actual_overtime'',''actual_bonus'',''forecast_allowances'',''annual_leave_pay'',''statutory_holiday_pay'',''sickness_allowance'')');
def:=replace(def,'IF f=''forecast_allowances'' AND s->>''pay_hours''<>''typed_monthly'' THEN RAISE EXCEPTION ''Hours come from rota'';END IF;','IF f=''forecast_allowances'' AND p.preparation->>''pay_basis'' IS DISTINCT FROM ''hour'' THEN RAISE EXCEPTION ''Confirm this person hourly pay basis first'';END IF;');
def:=replace(def,'old:=COALESCE((to_jsonb(p)->>f)::numeric,0);','old:=CASE WHEN f=''sickness_allowance'' THEN COALESCE((p.preparation->>''sickness_allowance'')::numeric,0) ELSE COALESCE((to_jsonb(p)->>f)::numeric,0) END;');
def:=replace(def,'EXECUTE format(''UPDATE public.hr_payroll SET %I=$1 WHERE id=$2 AND tenant_id=$3'',f) USING value,pid,t;','IF f=''sickness_allowance'' THEN UPDATE public.hr_payroll SET preparation=COALESCE(preparation,''{}''::jsonb)||jsonb_build_object(''sickness_allowance'',value) WHERE id=pid AND tenant_id=t;ELSE EXECUTE format(''UPDATE public.hr_payroll SET %I=$1 WHERE id=$2 AND tenant_id=$3'',f) USING value,pid,t;END IF;');
def:=replace(def,'+p.annual_leave_pay-p.unpaid_leave_deduction+','+p.annual_leave_pay+p.statutory_holiday_pay+COALESCE((p.preparation->>''sickness_allowance'')::numeric,0)-p.sick_leave_deduction-p.unpaid_leave_deduction+');
EXECUTE def;
END $$;
COMMENT ON FUNCTION public.payroll_override(uuid,uuid,text,numeric,numeric,text,boolean,integer) IS 'Exact confirmed human pay instructions including typed hourly inputs and source-linked leave/holiday/sickness payouts; no rota requirement and no saved posted/paid row changes.';